    VALUES ('Двойные согласные пишутся в словах:', 'MULTI_ANSWER'::question_type, 109, 7, NULL, NULL, NULL)
    RETURNING id
)
INSERT INTO answer_options (question_id, text, is_correct)
SELECT q.id, v.text, v.is_correct FROM q, (VALUES
    ('а(к/кк)омпанемент', TRUE),
    ('сея(н/нн)ые травы', FALSE),
    ('сдержа(н/нн)ость', TRUE),
    ('ко(р/рр)идор', FALSE),
    ('дореформе(н/нн)ый период', TRUE)
) AS v(text, is_correct);

